import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address newOwner) public {
        // Full admissible domain: any address, including address(0), may be proposed.
        // This test contract is the owner (constructor assigns _msgSender()).
        vm.prank(address(this));
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: whenever the ownership transfer succeeds, the owner must
        // become exactly the proposed address AND that address must be nonzero —
        // ownership can never be transferred to address(0) via transferOwnership.
        assertTrue(!ok || (ok && newOwner != address(0) && c.owner() == newOwner));
    }
}

